"""Randomized differential test: next_run vs minute-by-minute brute force."""

import random
import sys
from datetime import datetime, timedelta

sys.path.insert(0, "/private/tmp/tmpax74lulg/pete/projects/devkit")

from devkit.cron import next_run

DT = datetime


def add_years(moment, years):
    try:
        return moment.replace(year=moment.year + years)
    except ValueError:
        return moment.replace(year=moment.year + years, day=28)


def field_text(values, full, minimum, maximum):
    if full:
        return "*"
    return ",".join(str(v) for v in sorted(values))


def matches(candidate, mins, hrs, doms, months, dows, dom_restricted, dow_restricted):
    if candidate.minute not in mins or candidate.hour not in hrs:
        return False
    if candidate.month not in months:
        return False
    dom_ok = candidate.day in doms
    dow_ok = (candidate.weekday() + 1) % 7 in dows
    if dom_restricted and dow_restricted:
        return dom_ok or dow_ok
    return dom_ok and dow_ok


def brute(expr, after, mins, hrs, doms, months, dows, dom_restricted, dow_restricted):
    candidate = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = add_years(after, 5)
    while candidate <= limit:
        if matches(candidate, mins, hrs, doms, months, dows, dom_restricted, dow_restricted):
            return candidate
        candidate += timedelta(minutes=1)
    raise ValueError("no match")


rng = random.Random(20261027)

for case in range(40):
    # Random field values, with "*" used exactly when the full set is chosen.
    if rng.random() < 0.5:
        mins = set(range(60))
        min_full = True
    else:
        mins = set(rng.sample(range(60), rng.randint(1, 4)))
        min_full = False

    if rng.random() < 0.5:
        hrs = set(range(24))
        hr_full = True
    else:
        hrs = set(rng.sample(range(24), rng.randint(1, 3)))
        hr_full = False

    if rng.random() < 0.6:
        doms = set(range(1, 32))
        dom_full = True
    else:
        doms = set(rng.sample(range(1, 32), rng.randint(1, 3)))
        dom_full = False

    if rng.random() < 0.6:
        months = set(range(1, 13))
        mon_full = True
    else:
        months = set(rng.sample(range(1, 13), rng.randint(1, 3)))
        mon_full = False

    if rng.random() < 0.6:
        dows = set(range(7))
        dow_full = True
    else:
        raw = set(rng.sample(range(8), rng.randint(1, 3)))
        dows = {v % 7 for v in raw}
        dow_full = False

    # Serialize with numeric weekday 7 sometimes.
    if dow_full:
        dow_text = "*"
    else:
        dow_text = ",".join(str(v) for v in sorted(dows))

    expr = " ".join(
        [
            field_text(mins, min_full, 0, 59),
            field_text(hrs, hr_full, 0, 23),
            field_text(doms, dom_full, 1, 31),
            field_text(months, mon_full, 1, 12),
            dow_text,
        ]
    )

    after = DT(
        rng.randint(2000, 2030),
        rng.randint(1, 12),
        rng.randint(1, 28),
        rng.randint(0, 23),
        rng.randint(0, 59),
        rng.randint(0, 59),
        rng.randint(0, 999999),
    )

    try:
        expected = brute(
            expr,
            after,
            mins,
            hrs,
            doms,
            months,
            dows,
            not dom_full,
            not dow_full,
        )
    except ValueError:
        expected = None

    try:
        got = next_run(expr, after)
    except ValueError:
        got = None

    assert got == expected, (
        f"case {case}: {expr!r} after {after!r}\n"
        f"  got={got!r} expected={expected!r}"
    )
    print(f"case {case:02d}: {expr!r} after {after} -> {got}")

print("DIFFERENTIAL TESTS PASSED")
